public struct FfiConverterTypeSoundscapeCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = SoundscapeCore

    public static func lift(_ handle: UInt64) throws -> SoundscapeCore {
        return SoundscapeCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: SoundscapeCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SoundscapeCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SoundscapeCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


